import{_ as t,J as o,b as i,e as r,a8 as n,f as s,L as c}from"./chunks/framework.CumEd6mW.js";const R=JSON.parse('{"title":"GR32_VPR","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_VPR","entity":"GR32_VPR","kind":"Unit","summary":"Vectorial Polygon Rasterizer engine providing low-level analytical anti-aliased coverage rendering.","title":"GR32_VPR","date":1788853169000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_VPR/index.md","filePath":"api/GR32_VPR/index.md","lastUpdated":1788853169000,"timestamp":1788853169000,"datetime":"2026-09-08T07:39:29.000Z"}'),l={name:"api/GR32_VPR/index.md"};function d(p,e,g,u,h,m){const a=o("ApiMembers");return i(),r("div",null,[e[0]||(e[0]=n('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_VPR</code> unit implements the core <strong>Vectorial Polygon Rasterizer (VPR)</strong> algorithm for Graphics32. Designed by Mattias Andersson, VPR is an analytical coverage-based polygon rasterization engine that computes exact sub-pixel area coverage for vector polygon edges without the performance bottlenecks of traditional scanline edge-sorting algorithms.</p><h3 id="use-case-architecture" tabindex="-1">Use Case &amp; Architecture <a class="header-anchor" href="#use-case-architecture" aria-label="Permalink to &quot;Use Case &amp; Architecture&quot;">​</a></h3><p><code>GR32_VPR</code> provides low-level, high-performance rasterization functions (<code>RenderPolygon</code> and <code>RenderPolyPolygon</code>) that convert vector polygon contours (<code>TArrayOfFloatPoint</code> or <code>TArrayOfArrayOfFloatPoint</code>) into horizontal coverage spans (<code>TValueSpan</code>).</p><p>This unit is primarily used as the underlying rasterization engine for:</p><ul><li><a href="/api/GR32_Polygons/TPolygonRenderer32VPR/">TPolygonRenderer32VPR</a> and related vector polygon renderers in the <a href="/api/GR32_Polygons/">GR32_Polygons</a> unit.</li><li>Custom rasterization pipelines requiring direct access to analytical anti-aliasing coverage values per scanline.</li></ul><p>For a detailed technical explanation of the pipeline, mathematical integration of line segments, and cumulative prefix sum architecture, see the <a href="/guide/vpr">Vectorial Polygon Rasterizer</a> guide.</p>',7)),s("p",null,[c(a,{type:"members"})])])}const P=t(l,[["render",d]]);export{R as __pageData,P as default};
